,0.08189,0.965,0.45155,"312ba134598fe6729adf41f5",1250,1409,null,null],[22,6,0.50818,0.58728,0.965,0.81175,"7a37775d39c007d30e7be3e4",1250,856,null,null],[23,7,0.035,0.08254,0.49727,0.30767,"240433f0794e637897603680",1250,848,null,null],[24,7,0.035,0.47896,0.49727,0.7478,"7209fa6b7a6c2b9cec7d46c8",1250,1013,null,null],[25,7,0.50727,0.11974,0.965,0.18923,"36506a7df2c0ffd3faf4983a",1250,264,null,null],[26,7,0.50727,0.47798,0.965,0.51256,"63a3607fdc9f25ed8886af3e",1250,132,null,null],[27,8,0.035,0.08287,0.49727,0.16835,"78eb678a2d7b2c14d460bc7b",1250,322,null,null],[28,8,0.035,0.48483,0.49727,0.5814,"f69707565fc42c5009c9247d",1250,364,null,null],[29,8,0.50727,0.08254,0.965,0.16737,"a5a8c2f5673e3b1743e59d0e",1250,323,null,null],[30,8,0.50727,0.49299,0.965,0.54421,"5905a898c55c5be38d284ebd",1250,195,null,null]]]
]$papers$::jsonb) p
), records as (
 select p.*,(q->>0)::integer as number,(q->>1)::integer as page,
  jsonb_build_array(q->2,q->3,q->4,q->5) as crop,'/exam-images/q-'||(q->>6)||'.webp' as asset,
  (q->>7)::integer as width,(q->>8)::integer as height,(q->>9)::numeric as rate,q->>10 as level
 from papers p cross join lateral jsonb_array_elements(questions) q
), classified as (
 select r.*, md5('archive-question:'||sid||':'||section||':'||variant||':'||number)::uuid as id,
  jsonb_build_object('calendar_year',year,'month',month,'grade',grade,'provider',provider,'section',section,'variant',variant,
   'question_no',number,'needs_review',true,'method','official_archive') as classification
 from records r
)
select id,sid::uuid,grade,section,variant,number,page,crop,asset,width,height,title||' '||number||'번'||case when form<>'' then ' · '||form else '' end as title,
 source,curriculum,classification,url,label,board,publisher,rate,level,rate_source,
 (case section when 'math-a' then '수학 가형' when 'math-b' then '수학 나형' when 'type-a' then '수학 A형' when 'type-b' then '수학 B형'
      when 'natural' then '수리 자연계' when 'humanities' then '수리 인문계' when 'humanities-arts' then '수리 인문·예체능계' when 'arts' then '수리 예체능계'
      when 'math-a-integral' then '미분과 적분' when 'math-a-probability' then '확률과 통계' when 'math-a-discrete' then '이산수학' else '수학' end) as subject
from classified;

insert into public.exam_questions(id,session_id,variant,section,question_no,official_url,pdf_start_page,pdf_page,crop,classification,asset_path,width,height)
select id,sid,variant,section,number,url,1,page,crop,classification,asset,width,height from early_csat_1994_2001
on conflict(id) do nothing;
alter table public.problems disable trigger problems_rate;
alter table public.problems disable trigger problems_reward;
insert into public.problems(id,owner_id,exam_question_id,title,question,grade,subject,unit,curriculum_id,source,source_details,public,rights_confirmed)
select id,null,id,title,'공식 기출 수학 문제입니다.',grade,subject,'미분류',curriculum,source,
 jsonb_build_object('label',label,'board_url',board,'official_url',url,'pdf_page',page,'pdf_start_page',1,'crop',crop,
  'provider_name',publisher,'classification',classification,'asset_path',asset,'width',width,'height',height,'reference_only',true,'native_scan',true),
 true,true from early_csat_1994_2001
on conflict(id) do nothing;
alter table public.problems enable trigger problems_rate;
alter table public.problems enable trigger problems_reward;

do $$begin
 if (select count(*) from early_csat_1994_2001 h
  join public.exam_questions q on q.id=h.id and q.session_id=h.sid and q.question_no=h.number
   and q.variant=h.variant and q.section=h.section and q.asset_path=h.asset and q.crop=h.crop
  join public.problems p on p.exam_question_id=q.id and p.public and p.source_details->>'asset_path'=h.asset) <> 550
 then raise exception 'Early CSAT registration is incomplete'; end if;
end$$;
commit;
